package com.pointverse.app;

import android.test.InstrumentationTestCase;
import org.json.*;
import java.io.*;
import java.util.*;

@SuppressWarnings("deprecation")
public final class ImageGenerationTest extends InstrumentationTestCase {
    static final class State implements ImageGeneration.Pending {String value="";public String read(){return value;}public void write(String value){this.value=value;}}
    private JSONObject text(String content)throws Exception{return new JSONObject().put("choices",new JSONArray().put(new JSONObject().put("message",new JSONObject().put("content",content))));}
    private JSONObject job(String status)throws Exception{return new JSONObject().put("id",UUID.randomUUID().toString()).put("status",status);}
    public void testLongIdeaIsSummarizedBeforeImageWithoutDroppingSource()throws Exception {State state=new State();String source="完整想法".repeat(300);List<String> paths=new ArrayList<>();ImageGeneration flow=new ImageGeneration((path,method,payload)->{paths.add(path);if(path.contains("chat")){assertEquals(source,payload.getJSONArray("messages").getJSONObject(1).getString("content"));return text("A red cup beside a window, soft morning light");}assertEquals("A red cup beside a window, soft morning light",payload.getString("prompt"));return job("succeeded");},state,"account","pointverse-cloud",value->{});flow.generate(source);assertTrue(paths.get(0).contains("chat"));assertTrue(paths.get(1).contains("images"));assertEquals(source,new JSONObject(state.value).getString("source"));}
    public void testVeryLongIdeaIncludesLastSegmentThenCombinesSummaries()throws Exception {State state=new State();String source="甲".repeat(12000)+"末尾重要场景";List<String> inputs=new ArrayList<>();new ImageGeneration((path,method,payload)->{if(path.contains("chat")){String input=payload.getJSONArray("messages").getJSONObject(1).getString("content");inputs.add(input);return text("scene summary "+inputs.size());}return job("succeeded");},state,"account","pointverse-cloud",v->{}).generate(source);assertEquals(3,inputs.size());assertEquals("末尾重要场景",inputs.get(1));assertTrue(inputs.get(2).contains("scene summary 1")&&inputs.get(2).contains("scene summary 2"));}
    public void testResumeDoesNotRepeatTextModelOrCreateDuplicateImage()throws Exception {State state=new State();JSONObject done=job("succeeded");state.value=new JSONObject().put("source","原文").put("prompt","prepared prompt").put("account","account").put("request",UUID.randomUUID().toString()).put("job",done.getString("id")).toString();new ImageGeneration((path,method,payload)->{assertEquals("GET",method);assertTrue(path.endsWith(done.getString("id")));return done;},state,"account","pointverse-cloud",v->{}).generate("原文");}
    public void testExpiredJobGetsFreshRequestWithoutResummarizing()throws Exception {State state=new State();String old=UUID.randomUUID().toString();state.value=new JSONObject().put("source","原文").put("prompt","prepared prompt").put("account","account").put("request",old).put("job",UUID.randomUUID().toString()).toString();List<String> paths=new ArrayList<>();new ImageGeneration((path,method,payload)->{paths.add(path);if(method.equals("GET"))throw new NetworkModel.ServiceException(404,"job_not_found","expired");assertFalse(old.equals(payload.getString("request_id")));assertEquals("prepared prompt",payload.getString("prompt"));return job("succeeded");},state,"account","pointverse-cloud",v->{}).generate("原文");assertEquals(2,paths.size());}
    public void testDifferentOwnerCannotReuseSavedJob()throws Exception {State state=new State();state.value=new JSONObject().put("source","原文").put("prompt","old prompt").put("account","other").put("job",UUID.randomUUID().toString()).toString();new ImageGeneration((path,method,payload)->{assertEquals("POST",method);return path.contains("chat")?text("new prompt"):job("succeeded");},state,"account","pointverse-cloud",v->{}).generate("原文");assertEquals("account",new JSONObject(state.value).getString("account"));}
    public void testTextModelFailureNeverSubmitsOriginalIdeaToImageModel()throws Exception {State state=new State();try{new ImageGeneration((path,method,payload)->{assertTrue(path.contains("chat"));throw new IOException("text model failed");},state,"account","pointverse-cloud",v->{}).generate("原文");fail();}catch(IOException expected){assertEquals("",state.value);}}
    public void testFinalPromptIsUnicodeSafeAndBounded()throws Exception {State state=new State();new ImageGeneration((path,method,payload)->{if(path.contains("chat"))return text("😀".repeat(700));String prompt=payload.getString("prompt");assertEquals(600,prompt.codePointCount(0,prompt.length()));assertFalse(Character.isHighSurrogate(prompt.charAt(prompt.length()-1)));return job("succeeded");},state,"account","pointverse-cloud",v->{}).generate("原文");}
    public void testKnownErrorsHaveActionableMessages(){assertFalse(NetworkModel.serviceError(400,"invalid_request","/v1/ai/images/generations").getMessage().contains("服务暂不可用"));assertTrue(NetworkModel.serviceError(503,"image_queue_full","/v1/ai/images/generations").getMessage().contains("任务较多"));}
    public void testLensChangesPromptAndCannotReuseAnotherLensJob()throws Exception {State state=new State();state.value=new JSONObject().put("source","回忆").put("prompt","old").put("lens","original").put("account","account").put("job",UUID.randomUUID().toString()).toString();List<String> paths=new ArrayList<>();new ImageGeneration((path,method,payload)->{paths.add(path);assertEquals("POST",method);if(path.contains("chat")){assertTrue(payload.getJSONArray("messages").getJSONObject(0).getString("content").contains(ManifestationLens.prompt("dream")));return text("dreamlike memory");}assertEquals("dreamlike memory",payload.getString("prompt"));return job("succeeded");},state,"account","pointverse-cloud","dream",v->{}).generate("回忆");assertEquals(2,paths.size());assertEquals("dream",new JSONObject(state.value).getString("lens"));}

    public void testTransientCreateFailureRetriesSameRequestWithoutDuplicateJob()throws Exception {State state=new State();List<String> requests=new ArrayList<>();new ImageGeneration((path,method,payload)->{if(path.contains("chat"))return text("prepared scene");requests.add(payload.getString("request_id"));if(requests.size()==1)throw new NetworkModel.ServiceException(502,"ai_unavailable","temporary");return job("succeeded");},state,"account","pointverse-cloud",v->{}).generate("回忆");assertEquals(2,requests.size());assertEquals(requests.get(0),requests.get(1));}
    public void testTransientResumeFailureContinuesSavedJob()throws Exception {State state=new State();JSONObject done=job("succeeded");state.value=new JSONObject().put("source","回忆").put("prompt","scene").put("account","account").put("job",done.getString("id")).toString();java.util.concurrent.atomic.AtomicInteger calls=new java.util.concurrent.atomic.AtomicInteger();new ImageGeneration((path,method,payload)->{assertEquals("GET",method);if(calls.incrementAndGet()==1)throw new NetworkModel.ServiceException(502,"ai_unavailable","temporary");return done;},state,"account","pointverse-cloud",v->{}).generate("回忆");assertEquals(2,calls.get());}

}
